import fs from "node:fs";
import path from "node:path";
import typia from "typia";

import type { IHumanLexiconParams } from "../lexicon/IHumanLexiconParams";

/**
 * Writes `src/lexicon/HUMAN_LEXICON_SCHEMAS.json`: the JSON schema of every
 * lexicon row's open parameters, by row name, generated by typia from the
 * laws' own parameter types at compile time. Run by
 * `pnpm --filter @automovie/motions schemas`, which compiles this entry with
 * the typia transform; the first argument, when given, is the file to write
 * instead, which the drift test reads.
 *
 * @evidence contracts/development/common.md#meaningful-documentation States what is written, from what, by which command, and the argument.
 * @evidence contracts/development/implementation.md#principled-implementation typia's `json.schemas` reads the type the checker reads, so bounds and defaults come from each parameter's tags and meanings from its JSDoc; the root record's properties become the rows.
 * @evidence contracts/development/implementation.md#clear-and-simple-structure Generate, take the rows out of the root, write.
 * @evidence contracts/development/implementation.md#prohibited-implementation-shortcuts Nothing is edited by hand: the file says which command writes it.
 * @evidenceExclude contracts/development/implementation.md#efficient-algorithms One generation per run.
 * @evidenceExclude contracts/development/implementation.md#reuse-equivalent-work Nothing to cache.
 * @evidenceExclude contracts/development/implementation.md#bound-retention-and-release-resources Runs once and exits.
 */
export function lexiconSchemas(target?: string): void {
  const collection: ReturnType<typeof typia.json.schemas> =
    typia.json.schemas<[IHumanLexiconParams]>();
  const components: Record<string, { properties?: Record<string, object> }> =
    (collection.components.schemas ?? {}) as Record<
      string,
      { properties?: Record<string, object> }
    >;
  const root: { $ref?: string; properties?: Record<string, object> } =
    collection.schemas[0] as { $ref?: string; properties?: Record<string, object> };
  const rows: Record<string, object> =
    (root.$ref === undefined
      ? root.properties
      : components[root.$ref.split("/").at(-1)!]?.properties) ?? {};
  const sorted: Record<string, object> = Object.fromEntries(
    Object.keys(rows)
      .sort((a: string, b: string): number => a.localeCompare(b))
      .map((name: string): [string, object] => [name, rows[name]!]),
  );
  const out: string = target ?? path.join(__dirname, "../lexicon/HUMAN_LEXICON_SCHEMAS.json");
  fs.writeFileSync(
    out,
    `${JSON.stringify(
      {
        $comment:
          "Written by `pnpm --filter @automovie/motions schemas` from the lexicon laws' parameter types (src/executable/lexiconSchemas.ts); do not edit by hand.",
        version: collection.version,
        rows: sorted,
        components: collection.components,
      },
      null,
      2,
    )}\n`,
  );
}

lexiconSchemas(process.argv[2]);
